// RiskAlert – early-warning alert generated by configurable rules, reviewed by authorised humans.
// At most one open alert exists per user; new triggers are merged into it (duplicate prevention).
const mongoose = require('mongoose');

const ALERT_STATUSES = ['New', 'Under Review', 'Contact Initiated', 'Resolved'];

const triggerSchema = new mongoose.Schema({
    code: String,
    label: String,
    detail: String,
    checkinId: { type: mongoose.Schema.Types.ObjectId, ref: 'WellbeingCheckin' },
    at: { type: Date, default: Date.now },
}, { _id: false });

const reviewNoteSchema = new mongoose.Schema({
    authorId: { type: mongoose.Schema.Types.ObjectId, ref: 'User' },
    authorName: String,
    note: String, // private counselor note – encrypted at rest, never shown to the user
}, { timestamps: true });

const statusChangeSchema = new mongoose.Schema({
    from: String,
    to: String,
    changedBy: { type: mongoose.Schema.Types.ObjectId, ref: 'User' },
    changedAt: { type: Date, default: Date.now },
}, { _id: false });

const riskAlertSchema = new mongoose.Schema({
    alertRef: { type: String, required: true, unique: true },
    userId: { type: mongoose.Schema.Types.ObjectId, ref: 'User', required: true },
    caseRef: { type: String, required: true },
    checkinIds: [{ type: mongoose.Schema.Types.ObjectId, ref: 'WellbeingCheckin' }],
    latestAssessmentId: { type: mongoose.Schema.Types.ObjectId, ref: 'DistressAssessment' },
    category: { type: String, enum: ['Low Concern', 'Moderate Concern', 'High Concern', 'Urgent Support Needed'], required: true },
    score: Number,
    priority: { type: String, enum: ['normal', 'high', 'urgent'], default: 'normal' },
    triggerFactors: [triggerSchema],
    triggerCodes: [String],
    status: { type: String, enum: ALERT_STATUSES, default: 'New' },
    isOpen: { type: Boolean, default: true },
    assignedCounselor: { type: mongoose.Schema.Types.ObjectId, ref: 'User' },
    reviewNotes: [reviewNoteSchema],
    statusHistory: [statusChangeSchema],
    occurrences: { type: Number, default: 1 },
    lastTriggeredAt: { type: Date, default: Date.now },
    hasNewActivity: { type: Boolean, default: true },
    aiContext: {
        humanReviewRecommended: Boolean,
        confidence: String,
    },
    resolvedAt: Date,
    anonymized: { type: Boolean, default: false },
    isSynthetic: { type: Boolean, default: false },
}, { timestamps: true });

// Duplicate prevention: only one open alert per user at any time.
riskAlertSchema.index({ userId: 1 }, { unique: true, partialFilterExpression: { isOpen: true }, name: 'one_open_alert_per_user' });
riskAlertSchema.index({ assignedCounselor: 1, status: 1, updatedAt: -1 });
riskAlertSchema.index({ status: 1, category: 1, createdAt: -1 });
riskAlertSchema.index({ caseRef: 1, createdAt: -1 });

riskAlertSchema.statics.STATUSES = ALERT_STATUSES;

module.exports = mongoose.model('RiskAlert', riskAlertSchema);
